    keepMessage: '已保留当前输入，编辑对象与版本基准不变；可继续对照后手动调整再保存。',
    failPrefix: '载入最新内容失败：',
    syncList: true,
    onBegin: function () { setConflictActionsDisabled(true); },
    onResolve: function () { setConflictActionsDisabled(false); },
    onReject: function () { setConflictActionsDisabled(false); }
  });
}

cancelBtn.addEventListener('click', function () {
  if (saving || !editing) return;
  // 取消不提交任何修改，也不删除原文章，直接回到新建草稿状态
  if (isDirty() && !window.confirm('取消将放弃当前未保存的修改，原草稿不会被删除。确定取消编辑吗？')) {
    return;
  }
  enterCreateMode('已取消编辑，原草稿未改动。可以新建草稿。', null);
});

function fieldValue(text, isEmpty) {
  var dd = document.createElement('dd');
  if (isEmpty) {
    dd.className = 'empty-field';
    dd.textContent = '（空）';
  } else {
    dd.textContent = text;
  }
  return dd;
}

