    _handlers: {},
    value: '',
    textContent: '',
    className: '',
    hidden: false,
    disabled: false,
    type: '',
    name: '',
    rows: 0,
    classList: {
      _s: new Set(),
      add(c) { this._s.add(c); el.className = [...this._s].join(' '); },
