      _s: new Set(),
      add(c) { this._s.add(c); el.className = [...this._s].join(' '); },
      remove(c) { this._s.delete(c); el.className = [...this._s].join(' '); },
      contains(c) { return this._s.has(c); },
    },
    set textContent(t) { this._text = String(t); if (t !== '' ? false : true) { /* assign '' clears children like real DOM */ } this.children = []; },
    get textContent() { return this._text || ''; },
    _text: '',
