    addEventListener(t, fn) { (this._handlers[t] ||= []).push(fn); },
    click() { (this._handlers.click || []).forEach(f => f()); },
    focus() {},
    reset() { ids.title.value = ids.summary.value = ids.body.value = ''; },
    querySelectorAll(sel) {
          const out = [];
