  const assert = (c, m) => { if (!c) fail(m); };

  // Create v1 BEFORE evaluating the page script so initial list load sees it.
  let r = await api('POST', '/api/articles', { title: '标题v1', summary: '摘要v1', body: '正文v1' });
  const id = r.data.article.id;
  assert(r.data.article.version === 1, 'seed version 1');

  // eslint-disable-next-line no-new-func
  new Function(script)();
  await tick();

