  editBtn.click();
  await tick();
  assert(ids.title.value === '标题v1' && ids.body.value === '正文v1', 'loaded v1 into form');
  assert(ids['save-btn'].textContent === '保存修改', 'in editing mode label');
  assert(ids['edit-banner'].fullText.includes(id), 'banner shows article id');

  // User edits based on stale v1...
  ids.title.value = '旧页面的未保存标题';
  ids.summary.value = '旧摘要';
  ids.body.value = '旧正文\n第二段 <b>x</b>';

  // ...other page saves v2, then v3 (twice, as in the bug report)
  r = await api('PUT', '/api/articles/' + id, { title: '对方第一次保存v2', summary: 's2', body: 'b2', version: 1 });
  assert(r.status === 200 && r.data.article.version === 2, 'other page saves v2');

  // Old page submits based on v1 -> 409, conflict box shows
  ids['draft-form']._handlers.submit[0]({ preventDefault() {} });
  await tick(10);
  assert(!ids['conflict-box'].hidden, 'conflict box visible after 409');
  assert(ids.title.value === '旧页面的未保存标题', 'form input preserved after 409');
  let discardBtn = findButtons(b => b.textContent === '放弃当前输入并载入最新内容')[0];
  assert(discardBtn, 'discard button present');
  assert(ids['conflict-box'].fullText.includes('对方第一次保存v2'), 'comparison shows v2 content');

  // Other page saves AGAIN -> v3 while the stale comparison stays on screen
  r = await api('PUT', '/api/articles/' + id, {
    title: '对方第二次保存v3', summary: '', body: '多段\n\n<html>原样保留</html>', version: 2,
  });
  assert(r.data.article.version === 3, 'other page saves v3');

  // Click "discard & load latest": must GET current v3, not reuse the v2 409 snapshot.
  // Hold the GET so we can deterministically inspect the in-flight state.
  const release = armHold();
  discardBtn.click();
  await new Promise(r => setTimeout(r, 5)); // fetch has been intercepted and held
  assert(ids['save-btn'].disabled === true, 'save disabled while loading');
  assert(ids['cancel-btn'].disabled === true, 'cancel disabled while loading');
  assert(discardBtn.disabled === true, 'repeated reload disabled while loading');
  assert(ids.title.value === '旧页面的未保存标题', 'form NOT cleared at load start');
  // inputs still editable: user can type during load, then revert -> no confirm needed
  ids.body.value = '等待期间补写一行';
  ids.body.value = '旧正文\n第二段 <b>x</b>'; // reverted -> must NOT require confirm
  assert(/重新读取|载入/.test(ids.status.textContent), 'shows loading status: ' + ids.status.textContent);
  confirmReturns = ['SHOULD-NOT-BE-USED']; // reverted edit must not prompt
  release();
  await tick(10);

  assert(!ids['conflict-box'].hidden === false, 'conflict box hidden after load');
  assert(ids.title.value === '对方第二次保存v3', 'LOADED v3 TITLE (not stale v2): ' + ids.title.value);
  assert(ids.summary.value === '', 'loaded empty summary');
  assert(ids.body.value === '多段\n\n<html>原样保留</html>', 'loaded full multiline/HTML-like body verbatim');
  assert(ids['edit-banner'].fullText.includes(id), 'banner still same article id');
  // list card title/editing tag reflect the loaded result (walk the LIVE list subtree)
  const liveCards = [];
  (function walk(n) { n.children.forEach((c) => { if (c.tagName === 'ARTICLE') liveCards.push(c); walk(c); }); })(ids['article-list']);
  assert(liveCards.length === 1, 'exactly one live list card, got ' + liveCards.length);
  const card = liveCards[0];
  assert(card.className.includes('editing'), 'list card marked editing');
  assert(card.fullText.includes('对方第二次保存v3'), 'list card title updated to v3');
  assert(card.fullText.includes('编辑中'), 'editing tag shown');

  // Subsequent save must be based on loaded v3 -> succeeds as v4 on SAME article
  ids.title.value = '旧页面基于v3再修改';
  ids['draft-form']._handlers.submit[0]({ preventDefault() {} });
  await tick(10);
  const after = await api('GET', '/api/articles/' + id);
  assert(after.data.article.version === 4, 'next save advanced to v4 from loaded baseline, got ' + after.data.article.version);
  assert(after.data.article.title === '旧页面基于v3再修改', 'next save updated the same article');
  assert(ids['save-btn'].textContent === '保存修改', 'stays in editing mode after save');

  // ---- failure path: force a 404 by deleting server-side via data file is hard;
  // instead exercise the "edited during wait -> keep" branch using a fresh edit.
  ids['cancel-btn']._handlers.click[0](); // isDirty? form holds saved title? values: after save merge, title equals saved -> not dirty
  await tick();
  assert(ids.title.value === '', 'back to create mode after cancel');

  console.log('ALL BROWSER-LOGIC ASSERTIONS PASSED');
})().catch(e => { console.error(e); process.exit(1); });

