let hold = null;
globalThis.fetch = (url, opts) => {
  const u = typeof url === 'string' && url.startsWith('/') ? B + url : url;
  if (hold && typeof url === 'string' && url.startsWith('/api/articles/')
      && (!opts || !opts.method || opts.method === 'GET')) {
