    classList: { _s: new Set(), add(c){this._s.add(c);el.className=[...this._s].join(' ');},
      remove(c){this._s.delete(c);el.className=[...this._s].join(' ');}, contains(c){return this._s.has(c);} },
    set textContent(t){this._text=String(t==null?'':t);this.children=[];},
    get textContent(){return this._text+this.children.map(c=>c.textContent).join('');},
    appendChild(c){this.children.push(c);c.parentNode=this;return c;},
    addEventListener(t,fn){(this._handlers[t]||=[]).push(fn);},
