(async()=>{
  const fail=(m)=>{console.error('FAIL:',m);process.exit(1);};
  const assert=(c,m)=>{if(!c)fail(m);};
  const seed=await api('POST','/api/articles',{title:'种子','summary':'s','body':'b'});
  const id=seed.data.article.id;

  new Function(fs.readFileSync(process.env.PAGE,'utf8').match(/<script>([\s\S]*?)<\/script>/)[1])();
  await tick();
  buttons(b=>b.textContent==='编辑')[0].click();
  await tick();
  assert(ids.title.value==='种子','opened seed draft');

  // other page saves v2; old page edits and submits stale v1 -> 409
  await api('PUT','/api/articles/'+id,{title:'对方v2','summary':'s2','body':'b2',version:1});
  ids.title.value='我未保存的标题'; ids.body.value='我未保存正文';
  submit(); await tick(12);
  assert(!ids['conflict-box'].hidden,'conflict shown');

