  buttons(b=>b.textContent==='放弃当前输入并载入最新内容')[0].click();
  await new Promise(r=>setTimeout(r,5));
  assert(ids.title.value==='我未保存的标题','form not cleared while reload in flight (404)');
  releaseA(); await tick(12);
  assert(/载入最新内容失败/.test(ids.status.textContent),'shows reload failure reason: '+ids.status.textContent);
  assert(ids.title.value==='我未保存的标题' && ids.body.value==='我未保存正文','ALL inputs preserved after failure');
  assert(ids['save-btn'].disabled===false && ids['save-btn'].textContent==='保存修改','save restored & still editing label');
  assert(ids['cancel-btn'].hidden===false,'still in editing mode (cancel visible), not new-draft mode');
  assert(ids['edit-banner'].hidden===false,'edit banner retained');
  assert(!ids.status.classList.contains && true || true,'');
  const discardStill = buttons(b=>b.textContent==='放弃当前输入并载入最新内容')[0];
  assert(discardStill.disabled===false,'conflict actions operable again after failure');

  // restore the article (simulate it coming back / recreate baseline for next scenario):
  // Easier: reseed a brand-new draft for scenario B.
  hideAndContinue();
  await tick();
  function hideAndContinue(){ buttons(b=>b.textContent==='保留我的输入，继续修改')[0].click(); }

  // ---- Scenario B: fresh draft; during reload the user edits, then chooses KEEP ----
  const seed2=await api('POST','/api/articles',{title:'第二篇','summary':'','body':'正文B'});
  const id2=seed2.data.article.id;
  await tick(); // list re-render? list only refreshes on its own actions; but we added via API, need reopen button:
