   querySelectorAll(){const o=[];(function w(n){n.children.forEach(c=>{if(c.tagName==='BUTTON')o.push(c);w(c);});})(e);return o;}};return e;}
  ['draft-form','title','summary','body','save-btn','cancel-btn','status','edit-banner','conflict-box','article-list','empty-tip']
    .forEach((id)=>data.ids[id]=el(id==='draft-form'?'form':(id==='title'?'input':(id==='save-btn'||id==='cancel-btn'?'button':(id==='article-list'?'ul':'div')))));
