  const t=async(n=8)=>{for(let i=0;i<n;i++)await new Promise(r=>setTimeout(r,5));};
  const btns=(p)=>data.tracked.filter(x=>x.tagName==='BUTTON'&&p(x));
  return {
    async run(id, origTitle){
      await t();
      btns(b=>b.textContent==='编辑')[0].click();
      await t();
