const fs = require('node:fs');
const B = process.env.BASE;
const DATA = process.env.DATA;
const _fetch = globalThis.fetch;
globalThis.fetch = (url, opts) => {
  const u = typeof url === 'string' && url.startsWith('/') ? B + url : url;
  return _fetch(u, opts);
};
const tick = async (n = 10) => { for (let i = 0; i < n; i++) await new Promise(r => setTimeout(r, 5)); };
async function api(m, p, b) {
  const r = await fetch(B + p, { method: m, headers: b ? { 'content-type': 'application/json' } : undefined, body: b ? JSON.stringify(b) : undefined });
  return { status: r.status, data: await r.json() };
}
const PAGE_SCRIPT = fs.readFileSync(process.env.PAGE, 'utf8').match(/<script>([\s\S]*?)<\/script>/)[1];
const fail = (m) => { console.error('FAIL:', m); process.exit(1); };
const assert = (c, m) => { if (!c) fail(m); };

function makeContext() {
  const ctx = { ids: {}, tracked: [], confirms: [], hold: null };
  function el(tag) {
    const e = {
      tagName: tag.toUpperCase(), children: [], _handlers: {}, value: '', _text: '',
      className: '', hidden: false, disabled: false, type: '', name: '', rows: 0,
      classList: { _s: new Set(), add(c){this._s.add(c);e.className=[...this._s].join(' ');},
        remove(c){this._s.delete(c);e.className=[...this._s].join(' ');}, contains(c){return this._s.has(c);} },
      set textContent(t){this._text=String(t==null?'':t);this.children=[];},
      get textContent(){return this._text+this.children.map(c=>c.textContent).join('');},
      appendChild(c){this.children.push(c);c.parentNode=this;return c;},
      addEventListener(t,f){(this._handlers[t]||=[]).push(f);},
      click(){(this._handlers.click||[]).forEach(f=>f());}, focus(){},
      reset(){ctx.ids.title.value=ctx.ids.summary.value=ctx.ids.body.value='';},
      querySelectorAll(){const o=[];(function w(n){n.children.forEach(c=>{if(c.tagName==='BUTTON')o.push(c);w(c);});})(e);return o;},
    };
    return e;
  }
  ['draft-form','title','summary','body','save-btn','cancel-btn','status','edit-banner','conflict-box','article-list','empty-tip']
    .forEach((id) => ctx.ids[id] = el(id==='draft-form'?'form':(id==='title'?'input':(id==='save-btn'||id==='cancel-btn'?'button':(id==='article-list'?'ul':'div')))));
  ctx.attach = () => {
    global.document = { getElementById:(i)=>ctx.ids[i], createElement:(t)=>{const x=el(t);ctx.tracked.push(x);return x;} };
    global.window = { confirm: () => ctx.confirms.shift() };
    const realFetch = globalThis.fetch;
    globalThis.fetch = (url, opts) => {
      const u = typeof url === 'string' && url.startsWith('/') ? B + url : url;
      if (ctx.hold && typeof url === 'string' && url.startsWith('/api/articles/')
          && (!opts || !opts.method || opts.method === 'GET')) {
        const g = ctx.hold; ctx.hold = null;
        return g.then(() => realFetch(u, opts));
      }
      return realFetch(u, opts);
    };
  };
  ctx.arm = () => { let r; ctx.hold = new Promise(res => { r = res; }); return () => r(); };
  ctx.btns = (p) => ctx.tracked.filter(x => x.tagName === 'BUTTON' && p(x));
  ctx.submit = () => ctx.ids['draft-form']._handlers.submit[0]({ preventDefault(){} });
  return ctx;
}

(async () => {
  // ===== Scenario A: reload after conflict -> article deleted meanwhile (404) =====
  const seed = await api('POST', '/api/articles', { title: '种子A', summary: 's', body: 'b' });
  const idA = seed.data.article.id;
