  await new Promise(r => setTimeout(r, 5));
  assert(A.ids.title.value === '我未保存的标题', 'A: form not cleared while loading');
  assert(A.ids['save-btn'].disabled === true, 'A: save disabled in flight');
  relA(); await tick(12);
