  C.submit(); await tick(12);
  assert(!C.ids['conflict-box'].hidden, 'B: conflict shown');
  const relB = C.arm();
  C.confirms = [false]; // choose KEEP when prompted about concurrent edits
  C.btns(b => b.textContent === '放弃当前输入并载入最新内容')[0].click();
  await new Promise(r => setTimeout(r, 5));
  C.ids.title.value = '等待期间又改的标题'; // edit during wait
  relB(); await tick(12);
  assert(C.ids.title.value === '等待期间又改的标题' && C.ids.body.value === '我的正文', 'B: KEEP retains all inputs');
  assert(C.ids['save-btn'].textContent === '保存修改', 'B: KEEP still editing same draft');
  assert(/保留当前输入/.test(C.ids.status.textContent), 'B: KEEP status explains retention');
  // baseline must remain the original stale version -> another save is still 409
  C.submit(); await tick(12);
  assert(!C.ids['conflict-box'].hidden, 'B: baseline unchanged -> re-save still conflicts (no auto overwrite)');
  const cur = await api('GET', '/api/articles/' + idB);
  assert(cur.data.article.title === '对方改的v2' && cur.data.article.version === 2, 'B: saved record untouched');

  // ===== normal new-draft creation still works, on a separate record =====
  C.confirms = [true]; // confirm discard dirty edit on cancel
  C.ids['cancel-btn']._handlers.click[0]();
  await tick();
  assert(C.ids.title.value === '' && C.ids['save-btn'].textContent === '保存草稿', 'B: back to create mode');
  C.ids.title.value = '全新草稿'; C.ids.body.value = '全新正文 多段';
  C.submit(); await tick(14);
  const list = await api('GET', '/api/articles');
  const created = list.data.articles.find(a => a.title === '全新草稿');
  assert(created && created.version === 1, 'B: new draft created as v1');
  assert(created.id !== idB, 'B: create is a separate record; conflicted draft untouched');
  console.log('Scenario B (KEEP keeps inputs+baseline; new draft creation intact) PASSED');

  console.log('ALL EXTRA ASSERTIONS PASSED');
})().catch(e => { console.error(e); process.exit(1); });

