  const c = ctx();
  new Function(SCRIPT)();
  await tick();
  c.btns(b => b.textContent === '编辑')[0].click();
  await tick();
  assert(c.ids.title.value === '原始标题', 'startEdit trims title on load (server stored trimmed)');

  // conflict: other saves v2 then v3; old page stuck at v1
  await api('PUT', '/api/articles/' + id, { title: 'v2标题', summary: '', body: 'v2', version: 1 });
