  assert(c.ids.summary.value === 'v3摘要', 'DISCARD: summary from fresh read');
  assert(c.ids.body.value === '行一\n\n行二 <html>', 'DISCARD: multiline/HTML-like body intact');
  assert(c.ids['conflict-box'].hidden, 'conflict box closed after load');
  assert(c.ids['edit-banner'].fullText.includes(id), 'still same article id in banner');
  // save now based on v3 -> v4 succeeds
  c.submit(); await tick(14);
  const after = await api('GET', '/api/articles/' + id);
  assert(after.data.article.version === 4, 'next save advances v3->v4 on same article, got ' + after.data.article.version);
  assert(after.data.article.title === 'v3最新', 'saved content equals loaded baseline (no concurrent change)');
  assert(c.ids['save-btn'].textContent === '保存修改', 'remains editing after save');
  console.log('DISCARD-with-concurrent-edit + same-article update PASSED');
})().catch(e => { console.error(e); process.exit(1); });

